// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether + 1, 1000 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        uint256 bal = c.balances(actor);

        // withdraw exactly the full balance
        vm.prank(actor);
        c.CashOut(bal);

        assertTrue(c.balances(actor) == 0);
    }
}
